const listExpiredInvoices = `-- name: ListExpiredInvoices :many
SELECT id, expires_at::timestamptz AS expires_at FROM billing.invoices
WHERE merchant_id = $1::uuid AND collection_owner = 'engine' AND status = 'open'
  AND expires_at <= $2::timestamptz
  AND ($3::timestamptz IS NULL
       OR (expires_at, id) > ($3::timestamptz, $4::uuid))
ORDER BY expires_at, id
LIMIT $5::int
`

type ListExpiredInvoicesParams struct {
	MerchantID     uuid.UUID
	Now            time.Time
	AfterExpiresAt *time.Time
	AfterID        *uuid.UUID
	RowLimit       int32
}

type ListExpiredInvoicesRow struct {
	ID        uuid.UUID
	ExpiresAt time.Time
}

// A merchant's live purchases past their expiry (no other invoice has one), in
// expiry order after a cursor.
func (q *Queries) ListExpiredInvoices(ctx context.Context, arg ListExpiredInvoicesParams) ([]ListExpiredInvoicesRow, error) {
	rows, err := q.db.Query(ctx, listExpiredInvoices,
		arg.MerchantID,
		arg.Now,
		arg.AfterExpiresAt,
		arg.AfterID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListExpiredInvoicesRow
	for rows.Next() {
		var i ListExpiredInvoicesRow
		if err := rows.Scan(&i.ID, &i.ExpiresAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listInvoiceExpiryMerchants = `-- name: ListInvoiceExpiryMerchants :many
SELECT merchant_id FROM (
    SELECT merchant_id FROM billing.invoices
    WHERE collection_owner = 'engine' AND status = 'open' AND expires_at <= $1::timestamptz
      AND merchant_id > $2::uuid
    UNION
    SELECT merchant_id FROM billing.invoice_attempts
    WHERE expires_at IS NOT NULL AND expires_at < $1::timestamptz
      AND deleted_at IS NULL AND status IN ('created', 'requires_action')
      AND merchant_id > $2::uuid
) due
ORDER BY merchant_id
LIMIT $3::int
`

