	rows, err := q.db.Query(ctx, listInvoiceExpiryMerchants, arg.Now, arg.AfterMerchantID, arg.MerchantLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
