// An attempt starts on an open invoice: one that takes payment, or awaits the
// customer's action on an attempt that has since ended.
// Admission is durable before provider execution: a lost process must not make
// potentially billable work look like a cart that still needs a payment method.
func (q *Queries) StartInvoiceAttempt(ctx context.Context, arg StartInvoiceAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, startInvoiceAttempt,
		arg.AttemptID,
		arg.PaymentMethodID,
		arg.PspID,
		arg.Now,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const voidRenewalInvoice = `-- name: VoidRenewalInvoice :execrows
UPDATE billing.invoices
SET status = 'void', voided_at = $1::timestamptz, updated_at = $1::timestamptz,
    payment_id = $2::uuid,
    payment_status = CASE WHEN $2::uuid IS NULL THEN 'requires_payment_method' ELSE 'succeeded' END
WHERE merchant_id = $3::uuid AND id = $4::uuid
  AND origin = 'subscription' AND status IN ('open', 'processing')
`

type VoidRenewalInvoiceParams struct {
	Now        time.Time
	PaymentID  *uuid.UUID
	MerchantID uuid.UUID
	ID         uuid.UUID
}

// A live renewal its subscription's end left unowed. A payment that landed
// anyway stays on it (refunded).
func (q *Queries) VoidRenewalInvoice(ctx context.Context, arg VoidRenewalInvoiceParams) (int64, error) {
	result, err := q.db.Exec(ctx, voidRenewalInvoice,
		arg.Now,
		arg.PaymentID,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
